def semver_sort(versions):
    def parse(v):
        core = v
        build = ''
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = core.split('.')
        major, minor, patch = int(major), int(minor), int(patch)
        if pre is None:
            no_pre_flag = 1
            idents = []
        else:
            no_pre_flag = 0
            idents = []
            for part in pre.split('.'):
                if part.isdigit():
                    idents.append((0, int(part)))
                else:
                    idents.append((1, part))
        return (major, minor, patch, no_pre_flag, idents)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for i, v in indexed]

